import type { Booking } from '@prisma/client';
import { bookingConflict, notFound, validationFailed } from '../../shared/errors.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import { durationMinutes, isBefore, parseInstant } from '../../shared/time.js';
import { getRoom } from '../rooms/service.js';
import { getUser } from '../users/service.js';
import * as repository from './repository.js';
import { BOOKING_CANCELLED, MAX_DURATION_MINUTES, MIN_DURATION_MINUTES } from './schema.js';
import type { CreateBookingInput, ListBookingsInput, UpdateBookingInput } from './schema.js';

function assertValidWindow(startsAt: Date, endsAt: Date): void {
  if (!isBefore(startsAt, endsAt)) {
    throw validationFailed('endsAt must be after startsAt', { startsAt, endsAt });
  }
  const duration = durationMinutes(startsAt, endsAt);
  if (duration < MIN_DURATION_MINUTES || duration > MAX_DURATION_MINUTES) {
    throw validationFailed('Booking duration must be between 30 minutes and 8 hours', {
      minMinutes: MIN_DURATION_MINUTES,
      maxMinutes: MAX_DURATION_MINUTES,
      durationMinutes: duration,
    });
  }
}

function assertFuture(startsAt: Date): void {
  if (isBefore(startsAt, new Date())) {
    throw validationFailed('startsAt cannot be in the past', { startsAt });
  }
}

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
  const startsAt = parseInstant(input.startsAt);
  const endsAt = parseInstant(input.endsAt);
  assertValidWindow(startsAt, endsAt);
  assertFuture(startsAt);

  await getRoom(input.roomId);
  await getUser(input.userId);

  const result = await repository.createChecked({
    roomId: input.roomId,
    userId: input.userId,
    title: input.title,
    startsAt,
    endsAt,
  });
  if ('conflict' in result) {
    throw bookingConflict(result.conflict.id);
  }
  return result.booking;
}

export async function getBooking(id: string): Promise<Booking> {
  const booking = await repository.findById(id);
  if (!booking) {
    throw notFound('Booking');
  }
  return booking;
}

export async function listBookings(query: ListBookingsInput): Promise<Page<Booking>> {
  const limit = normalizeLimit(query.limit);
  const offset = normalizeOffset(query.offset);
  const [data, total] = await repository.list({
    roomId: query.roomId,
    userId: query.userId,
    status: query.status,
    from: query.from ? parseInstant(query.from) : undefined,
    to: query.to ? parseInstant(query.to) : undefined,
    limit,
    offset,
  });
  return paginated(data, total, limit, offset);
}

export async function updateBooking(id: string, input: UpdateBookingInput): Promise<Booking> {
  const existing = await getBooking(id);

  if (input.userId !== undefined) {
    await getUser(input.userId);
  }

  const data: Partial<repository.BookingData> = {
    ...(input.roomId !== undefined ? { roomId: input.roomId } : {}),
    ...(input.userId !== undefined ? { userId: input.userId } : {}),
    ...(input.title !== undefined ? { title: input.title } : {}),
    ...(input.startsAt !== undefined ? { startsAt: parseInstant(input.startsAt) } : {}),
    ...(input.endsAt !== undefined ? { endsAt: parseInstant(input.endsAt) } : {}),
  };

  const changesRoomOrSchedule =
    input.roomId !== undefined || input.startsAt !== undefined || input.endsAt !== undefined;

  if (!changesRoomOrSchedule) {
    return repository.update(id, data);
  }

  const roomId = data.roomId ?? existing.roomId;
  const startsAt = data.startsAt ?? existing.startsAt;
  const endsAt = data.endsAt ?? existing.endsAt;
  assertValidWindow(startsAt, endsAt);
  assertFuture(startsAt);

  if (input.roomId !== undefined) {
    await getRoom(input.roomId);
  }

  const result = await repository.updateChecked(id, data, { roomId, startsAt, endsAt });
  if ('conflict' in result) {
    throw bookingConflict(result.conflict.id);
  }
  return result.booking;
}

export async function cancelBooking(id: string): Promise<Booking> {
  const booking = await getBooking(id);
  if (booking.status === BOOKING_CANCELLED) {
    return booking;
  }
  return repository.updateStatus(id, BOOKING_CANCELLED);
}

export async function deleteBooking(id: string): Promise<void> {
  await getBooking(id);
  await repository.remove(id);
}

