  it('reports which booking caused the conflict', async () => {
    const first = await book(24, 25);
    const response = await book(24.5, 25.5, 'Overlap');
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  it('rejects a booking that starts before and ends inside an active booking', async () => {
    await book(24, 25);
    const response = await book(23.5, 24.5, 'Straddles start');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects a booking that fully contains an active booking', async () => {
    await book(24, 25);
    const response = await book(23.5, 25.5, 'Engulfs');
    expect(response.statusCode).toBe(409);
  });

  it('accepts a booking that ends exactly when another starts', async () => {
    await book(25, 26);
    const response = await book(24, 25, 'Before');
    expect(response.statusCode).toBe(201);
  });

  it('rejects a booking shorter than 30 minutes', async () => {
    const response = await book(24, 24.25, 'Too short');
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('rejects a booking longer than 8 hours', async () => {
    const response = await book(24, 33, 'Too long');
    expect(response.statusCode).toBe(400);
  });

  it('rejects a booking whose end is not after its start', async () => {
    const response = await book(25, 24, 'Backwards');
    expect(response.statusCode).toBe(400);
  });

  it('rejects a booking that starts in the past', async () => {
    const response = await book(-1, 0, 'Past');
    expect(response.statusCode).toBe(400);
  });

  it('rejects a booking for a room that does not exist', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId: 'missing-room', userId, title: 'Sync', startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(404);
  });

  it('rejects a booking for a user that does not exist', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId: 'missing-user', title: 'Sync', startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(404);
  });

  it('rejects moving a booking onto a conflicting slot via PATCH', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Movable');
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects moving a booking into a room with a conflict via PATCH', async () => {
    await book(24, 25);
    const other = await app.inject({
      method: 'POST',
      url: '/rooms',
      payload: { name: 'Borealis', capacity: 4 },
    });
    const movable = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: {
        roomId: other.json().id,
        userId,
        title: 'Elsewhere',
        startsAt: inHours(24),
        endsAt: inHours(25),
      },
    });
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${movable.json().id}`,
      payload: { roomId },
    });
    expect(response.statusCode).toBe(409);
  });

  it('allows moving a booking into a free slot via PATCH', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { startsAt: inHours(30), endsAt: inHours(31) },
    });
    expect(response.statusCode).toBe(200);
  });

  it('only one of two concurrent bookings for the same slot succeeds', async () => {
    const [first, second] = await Promise.all([book(24, 25, 'Race A'), book(24, 25, 'Race B')]);
    const statuses = [first.statusCode, second.statusCode].sort();
    expect(statuses).toEqual([201, 409]);
  });
});

